    fanInvestmentTitle: 'రివల్యూషనరీ ఫ్యాన్ ఇన్వెస్ట్ ‌ మెంట్ మోడల్',
    bettingTitle: 'ఫ్యూచర్ స్టార్ ‌ లపై పందెం వేయడం',
    bettingDesc: 'అభిమానులు విజయవంతమవుతారని వారు నమ్ముతున్న సృష్టికర్తలలో ఆర్థికంగా పెట్టుబడి పెట్టగల మొదటి ప్లాట్ ‌ ఫారమ్ ‌ ను DeHub సృష్టిస్తుంది. కంటెంట్ NFTల భిన్నాలను కొనుగోలు చేయడం ద్వారా, మద్దతుదారులు సృష్టికర్త ప్రయాణంలో వాటాదారులుగా మారతారు, వారు ఎంచుకున్న సృష్టికర్తలు ప్రకటన ఆదాయం, టిప్ ‌ లు మరియు ఇతర మోనటైజేషన్ స్ట్రీమ్ ‌ ల ద్వారా విజయం సాధించినప్పుడు రాబడిని పొందుతారు.',
    howFracWorks: 'ఫ్రాక్చరైజేషన్ ఎలా పని చేస్తుంది',
    fracStep1Title: '1. పోస్ట్ ‌ ను పుదీనా చేయండి',
    fracStep1Desc: 'పుదీనాను ఎంచుకోండి మరియు పోస్ట్ ERC-1155 NFT ఖచ్చితంగా 1,000 ట్రేడబుల్ భిన్నాలుగా విభజించబడుతుంది. దాన్ని దాటవేయండి మరియు పోస్ట్ ఇప్పటికీ ప్రచురిస్తుంది — మీరు దానిని తరువాత పుదీనా చేయవచ్చు.',
    fracStep2Title: '2. సృష్టికర్త నిర్ణయం',
    fracStep2Desc: 'సృష్టికర్తలు తమ 1,000 భిన్నాలలో ఎన్ని విక్రయించడానికి, ఉంచడానికి లేదా తమ సంఘానికి పంపిణీ చేయడానికి ఎంచుకుంటారు.',
    fracStep3Title: '3. ఫ్యాన్ ఇన్వెస్ట్ ‌ మెంట్',
    fracStep3Desc: 'మద్దతుదారులు భిన్నాలను కొనుగోలు చేస్తారు, అన్ని రెవెన్యూ స్ట్రీమ్ ‌ ల నుండి దామాషా రాబడిని సంపాదించే వాటాదారులుగా మారతారు.',
    benefitsTitle: 'అన్ని పార్టీలకు ప్రయోజనాలు',
    forCreators: 'సృష్టికర్తల కొరకు',
    forCreatorsDesc: 'తక్షణ మోనటైజేషన్, కమ్యూనిటీ ఫండింగ్, సమలేఖన ప్రోత్సాహకాలు మరియు విజయవంతమైన కంటెంట్ నుండి జీవితకాల నిష్క్రియాత్మక ఆదాయం.',
    forFans: 'అభిమానుల కోసం',
    forFansDesc: 'పెరుగుతున్న నక్షత్రాలకు మద్దతు ఇవ్వడం, వర్తకం చేయదగిన ఆస్తులు మరియు సృష్టికర్త విజయంలో ప్రత్యక్ష భాగస్వామ్యం నుండి ఆర్థికంగా పైకి.',
    forEveryone: 'ప్రతి ఒక్కరి కోసం',
    forEveryoneDesc: 'ప్లాట్ ‌ ఫారమ్ డిపెండెన్సీ లేకుండా పాల్గొనే వారందరికీ విలువను సృష్టించే సెన్సార్ ‌ షిప్-నిరోధక, అనుమతి లేని వ్యవస్థ.',
    comparisonTitle: 'SocialFi ప్లాట్ ‌ ఫారమ్ పోలిక',
    comparisonSubtitle: 'ప్రధాన వ్యత్యాసం: అవశేష వర్సెస్ క్రియాశీల విలువ సృష్టి',
    comparisonDesc: 'విలువను నిర్వహించడానికి సృష్టికర్తలు తమ టోకెన్ ‌ లు, షేర్లు లేదా కీలకు నిరంతరం విలువను జోడించాల్సిన ఇతర సోషల్ ‌ ఫై ప్లాట్ ‌ ఫారమ్ ‌ ల మాదిరిగా కాకుండా, DeHub కంటెంట్ జీవితానికి అవశేష ఆదాయాన్ని సృష్టిస్తుంది. సృష్టించిన తర్వాత, కంటెంట్ శాశ్వతంగా ప్రకటన ఆదాయాన్ని సంపాదిస్తుంది - క్రియేటర్ కృషి అవసరం లేకుండా అన్ని శాశ్వతత్వం కోసం నిష్క్రియాత్మక, అనుమతి లేని, సెన్సార్ ‌ షిప్-నిరోధక ఆదాయాన్ని అందిస్తుంది.',
