    commCreator2: 'సందేశ ప్రాప్యత మరియు ధరను నియంత్రించండి',
    commCreator3: 'గ్రూప్ చాట్ ‌ ల ద్వారా ప్రత్యేకమైన కమ్యూనిటీలను నిర్మించండి',
    commCreator5: 'ప్రతి ఇంటరాక్షన్ నుండి ఆదాయాన్ని సంపాదించండి',
    commForUsers: 'వినియోగదారుల కోసం',
    commUser2: 'ఇష్టమైన క్రియేటర్ ‌ ల నుండి ప్రత్యేకమైన కంటెంట్ ‌ ను యాక్సెస్ చేయండి',
