    spRotationTitle: 'స్లాట్ ఎలా షేర్ చేయబడింది',
    spRotationDesc: 'స్లాట్ పిన్ ‌ లకు బదులుగా తిరుగుతుంది. అనేక ప్రోత్సాహకాలు ఒకేసారి నడుస్తున్నప్పుడు, ప్రతి వీక్షకుడిని బూస్టర్ యొక్క బ్యాడ్జ్ శ్రేణితో వ్యవహరిస్తారు — అధిక శ్రేణి తరచుగా చూపబడుతుంది మరియు ప్రతి ఒక్కరూ వారు చెల్లించిన విండోను పొందుతారు. బూస్ట్ కొనుగోలు చేసేది నిర్దిష్ట సంఖ్యలో నిమిషాలకు వాయిస్ వాటా, ఫీడ్ పైభాగాన్ని మాత్రమే కలిగి ఉండదు.',
    spCycleTitle: 'ప్రతి ఒక్కరికీ ఒక గడియారం',
    spCycleDesc: 'సైకిల్ అనేది ప్లాట్ ‌ ఫారమ్-వైడ్ పద్నాలుగు రోజులు, కాబట్టి ప్రతి ఒక్కరి భత్యం ఒకే సమయంలో రీఫిల్ అవుతుంది. ఏదీ మారదు. బుకింగ్ ప్రారంభమయ్యే ముందు దానిని రద్దు చేయండి మరియు మీరు వారికి చెల్లించిన సైకిల్ ‌ లోకి నిమిషాలు తిరిగి వెళ్తాయి.',
    spSafetyTitle: 'ప్రోత్సాహకం ఏమి చేయదు',
    spSafetyDesc: 'ప్రతి డ్రా ఆ సమయంలో ఉన్నట్లుగా పోస్ట్ ‌ కు వ్యతిరేకంగా తిరిగి తనిఖీ చేయబడుతుంది, కాబట్టి అప్పటి నుండి తొలగించబడిన, బ్లాక్ చేయబడిన లేదా గుర్తించబడిన పోస్ట్ అపరిచితుడి ఫీడ్ ‌ కు చేరుకోదు. బుకింగ్ ‌ లో కూడా పరిపక్వ పోస్ట్ ‌ లు తిరస్కరించబడతాయి మరియు మిమ్మల్ని బ్లాక్ చేసిన వ్యక్తికి లేదా మీరు బూస్ట్ చేసిన వ్యక్తికి బూస్ట్ ఎప్పుడూ ఇవ్వబడదు.',
