    feeTierDesc: 'మా రివల్యూషనరీ ఫీజు స్ట్రక్చర్ గణనీయంగా తగ్గిన ప్లాట్ ‌ ఫారమ్ ఫీజుతో DeHub టోకెన్ హోల్డర్ ‌ లకు రివార్డ్ చేస్తుంది. ప్రామాణిక 10% రుసుముతో ప్రారంభించి, పెరిగిన టోకెన్ హోల్డింగ్ ‌ ల ద్వారా సంపాదించిన ప్రతి బ్యాడ్జ్ టైర్ ఫీజులను 0.69% తగ్గిస్తుంది, చివరికి మెగాలోడాన్ బ్యాడ్జ్ హోల్డర్ ‌ లకు కేవలం 1% కి చేరుకుంటుంది - మా అత్యంత అంకితమైన కమ్యూనిటీ సభ్యులకు 99% ఫీజు తగ్గింపు.',
