    predictionDescription: 'ఫలితాలను సరిగ్గా అంచనా వేయడం ద్వారా రివార్డ్‌లు పొందండి.',
    intro1: 'గేమర్స్ & స్ట్రీమర్ ‌ లతో నిండిన జట్టుగా, మేము అనేక ఆహ్లాదకరమైన, ఉచిత ఆర్కేడ్ ఆటలను నిర్మించాము మరియు విడుదల చేసాము మరియు మా మొదటి ఫ్లాగ్ ‌ షిప్ గేమ్, లాస్ట్ చాడ్ స్టాండింగ్, మొట్టమొదటి MMA బ్యాటిల్ రాయల్, ఉబిసాఫ్ట్ వంటి వాటికి చెందిన దేవ్ ‌ ల బృందంతో పాటు యుఎఫ్ ‌ సి, ఓక్టగాన్ మరియు పిఎఫ్ ‌ ఎల్ స్టార్ ‌ లతో భారీగా పాల్గొన్న వ్యవస్థాపక బృందం, జార్జ్ మస్విడాల్ వంటి చాంప్ ‌ లతో డాక్యుమెంటరీలను చిత్రీకరించడం మరియు కోనార్ మెక్ ‌ గ్రేగర్ కోచ్ కవన్నా కింద శిక్షణ పొందడం జరిగింది. డాక్యుమెంటరీలను ఆండ్రూ టేట్ యొక్క వార్ రూమ్ మరియు మాజీ యుఎఫ్ ‌ సి స్లగ్గర్ హెడ్ ల్యూక్ బార్నాట్ బెహాల్ ఆఫ్ డిహబ్ ‌ లో కూడా చిత్రీకరించారు.',
    intro2: 'నిశ్చితార్థం, సానుకూల ఫీడ్ ‌ బ్యాక్ లూప్ ‌ లు మరియు సాధారణ వృద్ధిని ప్రోత్సహించడానికి ఎటువంటి పలుచన లేదా ద్రవ్యోల్బణం అవసరం లేదని నిర్ధారించే ఫీజు ఉత్పత్తిపై పూర్తిగా ఆట మరియు సంపాదించే మోడల్.',
    intro3: 'ఉమ్మడి లక్ష్యాన్ని సాధించడానికి ఎక్కువ మంది వినియోగదారులుగా, ఎక్కువ ఆదాయాన్ని సంపాదించడానికి, ఎక్కువ రివార్డ్ ‌ లు ఉత్పత్తి చేయడానికి మరియు ఎక్కువ మంది వినియోగదారులను ఆకర్షించడానికి నిరంతరం కృషి చేయడానికి జట్టు మరియు సంఘాన్ని ప్రోత్సహించడం వల్ల కూడా ఇది అదనపు ప్రయోజనాన్ని కలిగి ఉంటుంది.',
    intro4: 'నిజంగా స్వీయ-పెంపొందించే మరియు స్థిరమైన పర్యావరణ వ్యవస్థ.',
