    chessDesc: 'ప్రతి ముక్క వెనుక ఒక సైన్యంతో సినిమాటిక్ 3D చదరంగం. మూడు మోసపూరిత నాగరికతలు నాలుగు యుద్ధభూమిలలో, మూడు ఇంజిన్ బలాలతో, ఎలోపై ఆన్ ‌ లైన్ నిచ్చెనతో ఒక పాలరాయి బోర్డు గుండా కవాతు, సమ్మె మరియు పడిపోతాయి.',
