    fairVoting: 'సరసమైన ఓటింగ్ తర్కం',
    fairVotingDesc: 'DeHub మెరుగైన ఓటింగ్ తర్కాన్ని ప్రవేశపెడుతోంది, ఇక్కడ వాటాదారుల బరువు పరిమిత మొత్తాల ద్వారా గుణించబడుతుంది, ఏ ఒక్క సంస్థ ప్రోటోకాల్ ‌ ను నియంత్రించలేదని నిర్ధారిస్తుంది, అయితే పెద్ద పెట్టుబడిదారులకు ఇప్పటికీ అనులోమానుపాతంలో రివార్డ్ ఇవ్వబడుతుంది. మేము కొత్త గేమ్ సిద్ధాంతాన్ని కూడా చేర్చాము, దీని ద్వారా ప్రతి ఓటుకు ఓటరు నిర్ణీత సంఖ్యలో DeHub టోకెన్ ‌ లను కాల్చాలి, ప్రస్తుతం 50. నిశ్చితార్థాన్ని ప్రోత్సహించేటప్పుడు ఇది చెడ్డ నటులను లేదా తారుమారుని మరింత ప్రోత్సహిస్తుంది, ఇది ప్రతి పోల్ ‌ లో ఓటు వేయడానికి ఎక్కువ మంది వినియోగదారులను ప్రోత్సహిస్తుంది.',
    preventingWhales: 'తిమింగలం తారుమారుని నివారించడం',
    preventingWhalesDesc: 'మా నవల ఓటింగ్ తర్కం ఏ ఒక్క సంస్థ కూడా ప్రోటోకాల్ ‌ ను నియంత్రించలేదని నిర్ధారిస్తుంది, అదే సమయంలో పెద్ద పెట్టుబడిదారులకు దామాషా ప్రకారం బహుమతి ఇస్తుంది.',
    encouragingEngagement: 'నిశ్చితార్థాన్ని ప్రోత్సహించడం',
    encouragingEngagementDesc: 'ఓటింగ్ కోసం బర్న్ అవసరం అర్ధవంతమైన భాగస్వామ్యాన్ని ప్రోత్సహిస్తుంది మరియు పనికిరాని లేదా హానికరమైన ఓటింగ్ ‌ ను నిరుత్సాహపరుస్తుంది.',
    solvingTitle: 'పరిపాలన సమస్యలను పరిష్కరించడం',
    solvingDesc: 'ప్రస్తుతం, టోకెన్ గవర్నెన్స్ యొక్క పేలవమైన కీర్తికి అత్యంత అపఖ్యాతి పాలైన రెండు కారణాలు వేల్ తారుమారు మరియు విస్తృత హోల్డర్ బేస్ నుండి నిశ్చితార్థం లేకపోవడం. పైన పేర్కొన్న ఓటింగ్ లాజిక్ మరియు గేమ్ థియరీ ప్రపంచవ్యాప్తంగా గుర్తించబడిన ఈ సమస్యలకు ఒక కొత్త పరిష్కారాన్ని అందిస్తుంది మరియు టోకెన్ గవర్నెన్స్ స్కెప్టిక్స్ తప్పు అని నిరూపించాలని మేము ఆశిస్తున్నాము.',
    launchNote: 'DeHub యొక్క గవర్నెన్స్ ప్రోటోకాల్ ప్లాట్ ‌ ఫారమ్ అంతటా విస్తరిస్తోంది — ఈ రోజు యాప్ ‌ లో ప్రతిపాదనలు మరియు ఓటింగ్ అందుబాటులో ఉన్నాయి.',
    stayTuned: 'మరిన్ని వివరాల కోసం వేచి ఉండండి...',
    disclaimer: 'నిరాకరణ',
    disclaimerText: 'DeHub టోకెన్ ‌ లు ఖచ్చితంగా యుటిలిటీ ప్రయోజనాల కోసం ఏదైనా ఆటలో లేదా యాప్ ‌ లో డిజిటల్ టోకెన్ ‌ లు లేదా కరెన్సీల మాదిరిగానే ఉంటాయి మరియు ఖచ్చితంగా పెట్టుబడి కాదు. మా టోకెన్ ఆన్-చైన్ ‌ లో ఉన్నందున, మేము అదనపు యుటిలిటీతో పాటు అపూర్వమైన ధృవీకరించదగిన పారదర్శకతను అందించగలము. పై డేటా పారదర్శకత, విద్యా మరియు సమాచార ప్రయోజనాల కోసం మాత్రమే సంకలనం చేయబడింది. మేము విడుదల చేసే టోకెన్ ‌ లు లేదా NFTలను కొనుగోలు చేయడం వల్ల కలిగే ఆర్థిక నష్టాలకు DeHub మరియు అన్ని అనుబంధ సంస్థలు బాధ్యత వహించవు. మార్కెట్ ‌ లు చాలా అస్థిరంగా ఉంటాయి. సామర్థ్య వైఫల్యాలు, సాంకేతిక లోపం, హక్స్ మొదలైన ఏవైనా ఊహించని లోపాల కారణంగా మీరు మీ డబ్బు మొత్తాన్ని కూడా కోల్పోవచ్చు. అందువల్ల, మీరు కోల్పోవటానికి భరించగలిగేది మాత్రమే మీరు ఖర్చు చేయాలి.',
