    stakeNow: 'ఇప్పుడే స్టేక్ చేయండి',
    introDesc: 'అన్ని డి \'యాప్ ‌ లలో మెరుగైన ఫీచర్ ‌ లను వివిధ క్లబ్ టైర్ ‌ లను యాక్సెస్ చేయడానికి మరియు ప్రోటోకాల్ ఆదాయంలో మీ వాటాను గని చేయడానికి మొబైల్ ‌ గా కొద్దిగా నుండి మీ కంప్యూటింగ్ పవర్ లేదా స్టోరేజ్ స్థలాన్ని అందించడానికి వాటా తీసుకోండి.',
    introDesc2: 'తదుపరి కేటాయింపులు ఇప్పుడు డైనమిక్ ‌ గా ఉంటాయి, ప్రోటోకాల్ ఫీజులపై ఆధారపడి ఉంటాయి, ప్రోటోకాల్ అవసరాలు అన్ని సమయాల్లో ముందంజలో ఉన్నాయని నిర్ధారిస్తూ ఏ సమయంలోనైనా హోదా అవసరాలకు లోబడి ఉంటుంది. స్టాకింగ్ ప్రోటోకాల్ కూడా ప్రస్తుతం బేస్ ‌ లో విడుదలతో అప్ ‌ గ్రేడ్ చేయబడుతోంది.',
    technicals: 'సాంకేతికతలు',
    technicalsDesc1: 'క్లబ్ ‌ లలో చేరడం మీ dehub.io ప్రొఫైల్, వ్యాఖ్యలు, అప్ ‌ లోడ్ ‌ లు మరియు లైవ్ చాట్ కమ్యూనికేషన్ ‌ లలో ప్రదర్శించబడే దిగువ బ్యాడ్జ్ ‌ లను కూడా అన్ ‌ లాక్ చేస్తుంది.',
    technicalsDesc2: 'స్టేక్ చేసిన DeHub టోకెన్ ‌ ల మొత్తానికి ప్రోత్సాహకాలకు మించి, వినియోగదారు రివార్డ్ ‌ లను నిర్వచించే వాటా వ్యవధి ద్వారా నిర్ణయించబడిన మూడు ముందే నిర్వచించిన టైర్లు కూడా ఉన్నాయి.',
