    rewardCalcDesc2: 'వినియోగదారులు స్టాకింగ్ నుండి వెంటనే రివార్డ్ ‌ లను పొందవచ్చు లేదా వారు స్టాకింగ్ చేసినప్పుడు బట్టి ఇంజెక్షన్ ‌ ల కోసం వేచి ఉండాల్సి ఉంటుంది.',
