    exampleA: 'యూజర్ A 1 త్రైమాసికానికి టైర్ 1లో ఉంచారు',
    exampleB: 'యూజర్ బి మొదటి రివార్డ్ తర్వాత 3 త్రైమాసికాలకు టైర్ 2లో నిలిచారు',
    exampleC: 'మొదటి రివార్డ్ తర్వాత 5 త్రైమాసికాలకు వినియోగదారు C టైర్ 3లో నిలిచారు',
    restakeRules: 'రీస్టేక్ నియమాలు',
