    restakeNote1: 'పునఃస్థాపించడం అంటే అన్ ‌ లాక్ చేసిన/లాక్ చేసిన టోకెన్ ‌ లు మరియు వాటాను మళ్లీ తీసివేయడం',
    restakeNote2: 'వినియోగదారులు అన్ ‌ లాక్ తేదీని చేరుకోవడానికి ముందు ఆటోమేటిక్ రీస్టేక్ బటన్ ‌ ను ఉపయోగించవచ్చు, అయితే ఇది పంట తేదీలకు వెలుపల 12% ఫీజుతో వస్తుంది',
    restakeNote3: 'ఆటోమేటిక్ ‌ గా రీస్టేక్ అయినప్పుడు, వినియోగదారులు లాకింగ్ వ్యవధిని మార్చవచ్చు',
    restakeNote4: 'లాక్ చేసిన టోకెన్ ‌ లను మాన్యువల్ ‌ గా రీస్టేక్ చేయమని వినియోగదారులు బలవంతం చేస్తే, మొత్తం మొత్తంలో 88% మాత్రమే POOLలో వాటా ఉంటుంది మరియు 12% మాత్రమే DEV వాలెట్ ‌ కు బదిలీ చేయబడుతుంది',
    howToStakeDesc: 'దశలు చాలా సరళమైనవి మరియు కనీస క్లిక్ ‌ లు లేదా సాంకేతిక అవసరాలను కలిగి ఉంటాయి.',
