    howRewardsGenerated: 'స్టాకింగ్ రివార్డ్ ‌ లు ఎలా సృష్టించబడతాయి',
    howRewardsDesc: 'నెట్ ‌ వర్క్ యొక్క ఆదాయ ప్రవాహాల ద్వారా తీసుకున్న అన్ని ఫీజుల నుండి అలాగే ప్రారంభ ఇంజెక్షన్ నుండి ప్రాథమిక కేటాయింపుల నుండి స్టాకింగ్ రివార్డ్ ‌ లు ఉత్పత్తి చేయబడతాయి.',
