    povrDesc3: 'బ్లాక్ స్థలం లేదా గ్యాస్ వృథా చేయకుండా వీక్షకులు నిజమైనవారని మీరు నిరూపించగలిగితే? ఖర్చులను ఆదా చేయడానికి మాత్రమే కాకుండా, మీ ప్రచారాల కోసం ROIని పెంచడానికి కూడా మీరు ప్రతి వాలెట్ యొక్క ఆర్థిక డేటాను ప్రభావితం చేయగలిగితే? కేవలం ఎక్కువ డబ్బు ఆదా చేయవద్దు, ఎక్కువ సంపాదించండి!',
    povrDesc4: 'పేటెంట్లు పెండింగ్ ‌ లో ఉన్న మా సాఫ్ట్ ‌ వేర్, ఈ మునుపటి ఫీచర్ స్పాట్ ‌ లైట్ ‌ లో హైలైట్ చేసిన మా ధృవీకరణ బ్యాడ్జ్ ‌ లతో కలిపి అపూర్వమైన 13-స్థాయి ర్యాంకింగ్ సిస్టమ్ ద్వారా దీన్ని చేస్తుంది.',
    povrDesc5: 'మేము దీనిని "ప్రూఫ్-ఆఫ్-వ్యూ-అండ్-ర్యాంక్" లేదా "POVR" అని పిలుస్తున్నాము.',
