    howItWorks: 'ఇది ఎలా పని చేస్తుంది',
    howItWorksDesc1: 'మీ మొత్తం హోల్డింగ్ ‌ లు, మీరు అన్ ‌ లాక్ చేసే అధిక ర్యాంకింగ్ బ్యాడ్జ్, ప్రకటనల నుండి మీరు ఎంత ఎక్కువ సంపాదిస్తారో, మీకు ప్రకటన ఇవ్వడానికి ఎక్కువ కంపెనీలు చెల్లిస్తాయి.',
    howItWorksDesc2: 'ఈ విధానము ఒక్క పార్టీకి మాత్రమే కాకుండా మొత్తం పర్యావరణ వ్యవస్థకు ప్రయోజనం చేకూరుస్తుంది. ప్లాట్ ‌ ఫారమ్ ‌ లో ప్రకటనలు చేసే కంటెంట్ సృష్టికర్తలు, వినియోగదారులు, హోల్డర్ ‌ లు మరియు కంపెనీలు అన్నీ ఎక్కువ రివార్డ్ ‌ లను పొందుతాయి.',
    howItWorksDesc3: 'ఆర్థిక డేటా అత్యంత లాభదాయకమైనది, మరియు ప్రేక్షకులను లక్ష్యంగా చేసుకోవడానికి ప్రకటనదారులు ఉపయోగించగల ఒక సిస్టమ్ ‌ లో మాది ప్రత్యేకంగా మిళితం చేయబడింది. ఇది మీరు ఆఫ్-చైన్ చేయగల విషయం కూడా కాదు, ఎందుకంటే బ్యాంక్ స్టేట్ ‌ మెంట్ ‌ లు ప్రైవేట్ ‌ గా ఉంటాయి, అయితే బ్లాక్ ‌ చైన్ పబ్లిక్ ‌ గా ఉంటుంది.',
    howItWorksDesc4: 'తిమింగలాలు మరియు పెద్ద ఖర్చుదారులను లక్ష్యంగా చేసుకుని, సముద్రంలోని చిన్న చేపల కోసం ప్రత్యేక డీల్స్ లేదా డిస్కౌంట్లను కూడా రూపొందించడం వల్ల ప్రకటనలు ప్రపంచవ్యాప్తంగా ఎలా పనిచేస్తాయో తిరిగి రూపుదిద్దుకుంటాయి. ఎవరూ దీనిని ఎందుకు కోరుకోరు?',
    preventFraud: 'ఇది మోసాన్ని ఎలా నిరోధిస్తుంది?',
    preventFraudDesc1: 'బాటింగ్ తక్కువ లాభదాయకంగా మారుతుంది, అయితే యాక్టివిటీ ఆన్-చైన్ ‌ ను ట్రాక్ చేయగలదు, చెడు నటీనటులను సులభంగా కనెక్ట్ చేస్తుంది మరియు చివరికి మొత్తం యూజర్ బేస్ ‌ ను క్యూరేట్ చేస్తుంది. ప్రకటనదారులు అధిక ర్యాంకులను లక్ష్యంగా చేసుకుంటారు, దిగువ పొరలో కనీస వెలికితీత విలువను వదిలివేస్తారు, ఇక్కడ ఏదైనా మోసం మిగిలి ఉంటుంది. ఆ పైన, మా వికేంద్రీకృత నియంత్రణ మరింత సమర్థవంతమైన అక్రమ కార్యకలాపాల గుర్తింపు మరియు నివారణను అనుమతిస్తుంది.',
    preventFraudDesc2: 'మా ప్రకటన ఆదాయ భాగస్వామ్యంపై మరింత సమాచారం కోసం, ఈ థ్రెడ్ మరియు దిగువ మా వైట్ ‌ పేపర్ ‌ ను చూడండి. అలాగే, యాప్ ఫీచర్ ‌ లు మరియు అప్ ‌ డేట్ ‌ లకు సంబంధించిన అన్ని తాజా వార్తల కోసం మమ్మల్ని అనుసరించండి.',
    dashboardPreview: 'ప్రకటనదారు డ్యాష్ ‌ బోర్డ్ పరిదృశ్యం',
    dashboardDesc: 'ప్రకటనదారు కోణం నుండి POVR అడ్వర్టైజింగ్ ప్లాట్ ‌ ఫారమ్ ‌ ను అనుభవించండి. ఈ ఇంటరాక్టివ్ ప్రివ్యూ DeHubలో ప్రకటన చేసే కంపెనీలకు అందుబాటులో ఉన్న సాధనాలు మరియు విశ్లేషణలను చూపిస్తుంది.',
    analytics: 'విశ్లేషణలు',
    budgetCalculator: 'బడ్జెట్ కాలిక్యులేటర్',
