    malRole: "సహ-స్థాపకుడు",
    malBio: "ఫుల్ స్టాక్ వెబ్ మరియు బ్లాక్‌చెయిన్ డెవలపర్, Pixcellor వద్ద AI వ్యాపార పరిష్కారాలను నిర్మిస్తున్నారు, Randstad లో పూర్వ సీనియర్ కన్సల్టెంట్, దాదాపు $10m లిక్విడిటీ పూల్ మరియు $2m మొదటి సంవత్సరంలో ఆదాయంతో DeHub ను £250m మార్కెట్ క్యాప్ శిఖరానికి పెంచారు. ఇంతకుముందు UK యొక్క అతిపెద్ద ఏజెన్సీ Blue Arrow లో వార్షిక టాప్ బిల్లింగ్ కన్సల్టెంట్ మరియు UK యొక్క అతిపెద్ద నిర్మాణ ఏజెన్సీ ITS వద్ద మొత్తం ప్రాంతాలను నిర్మించారు.",
    malExp1: "Guide Dogs: బహుళ రంగాలలో 5-10 మంది బృందంతో నిధుల సమీకరణ నిర్వాహకుడిగా >$1m సేకరించారు",
