    malExp3: "Blue Arrow: 600 మందికి పైగా సిబ్బంది మరియు దేశవ్యాప్తంగా 70 కార్యాలయాలతో UK యొక్క అతిపెద్ద ఏజెన్సీలో అతిపెద్ద బిల్లర్ & అవార్డు విజేత కన్సల్టెంట్. వారానికి $10,000 కంటే ఎక్కువ వ్యక్తిగత నికర మార్జిన్‌లను ఉత్పత్తి చేస్తున్నారు మరియు ఏ సమయంలోనైనా 100 మందికి పైగా పూర్తి లేదా పార్ట్ టైమ్ సిబ్బందితో వేలాది మందిని నియమించారు.",
    malExp4: "ITS Construction: ప్రముఖ UK నిర్మాణ ఏజెన్సీలో సస్సెక్స్ ప్రాంతీయ మేనేజర్. తన సొంత కార్యాలయాన్ని మొదటి నుండి నిర్మించారు మరియు 8 నెలల కంటే తక్కువ సమయంలో 0 నుండి వారానికి $5k కి మార్చారు, UK యొక్క అత్యంత ప్రతిష్టాత్మక బిల్డర్ బెర్కిలీ హోమ్స్‌తో PSL ను సంతకం చేశారు, $100bn హార్షమ్ ప్రాజెక్ట్‌లో ప్రత్యేక సరఫరాదారుగా గెలిచారు, హైవుడ్.",
