    paragraph2: 'DeHub ప్లాట్ ‌ ఫారమ్ ‌ లో DeHub టోకెన్ ‌ ల వాడకాన్ని తిరస్కరించే హక్కు DeHubకి ఉంది. ప్రత్యక్షంగా లేదా పరోక్షంగా ఉత్పన్నమయ్యే ఏదైనా ప్రత్యక్ష లేదా పర్యవసాన నష్టం లేదా నష్టానికి DeHub ఏదైనా బాధ్యతను తిరస్కరిస్తుంది: (i) అందించిన ఏదైనా సమాచారంపై ఆధారపడటం, (ii) అటువంటి సమాచారంలో ఏదైనా లోపం, మినహాయింపు లేదా ఖచ్చితత్వం; లేదా (iii) అటువంటి సమాచారం వల్ల కలిగే ఏదైనా చర్య.',
