    limitationOfLiability: 'బాధ్యత పరిమితి',
    limitationText: 'వికేంద్రీకృత ప్లాట్ ‌ ఫారమ్ ‌ గా, DeHub బాధ్యత ప్రోటోకాల్ యొక్క సాంకేతిక ఆపరేషన్ ‌ కు పరిమితం చేయబడింది. దీనికి మేము బాధ్యత వహించము:',
