    daoLink: 'DAO ట్రెజరీని తెరవండి',
    aboutTitle: 'DeHub గురించి',
    aboutP1: 'DeHub అనేది లాభాపేక్షలేని, వికేంద్రీకృత, వినియోగదారు యాజమాన్యంలోని ప్రోటోకాల్. మొత్తం నికర లాభం తిరిగి కొనుగోలు చేయడానికి మరియు DeHub టోకెన్ ‌ లను వాటాదారులతో పంచుకోవడానికి ఉపయోగించబడుతుంది.',
    aboutP2: 'అన్ని ఆదాయాలు DAO ప్రతిపాదనలకు అనుగుణంగా ఖర్చు చేయబడతాయి, పర్యావరణ వ్యవస్థలో 100% తిరిగి పెట్టుబడులు పెట్టడాన్ని నిర్ధారిస్తుంది. DeHub రెవెన్యూ మరియు విరాళాల ద్వారా ప్రజా ప్రయోజనంగా ఎప్పటికీ నిర్వహించబడుతుంది.',
