    reportingItem4: 'అత్యవసర లేదా చట్టపరమైన విషయాల కోసం, dev@dehub.ioకు ఇమెయిల్ చేయండి',
    whatHappensNext: 'తరువాత ఏమి జరుగుతుంది',
    whatHappensNextText: 'నియమించబడిన మోడరేటర్ ‌ లు — కమ్యూనిటీ-ఎన్నుకోబడిన నిర్వాహకులు మరియు అగ్రశ్రేణి బ్యాడ్జ్ హోల్డర్ ‌ లు — గవర్నెన్స్ ఓటు కోసం వేచి ఉండకుండా పనిచేయడానికి అప్పగించిన అధికారాన్ని కలిగి ఉన్న నివేదికలను సమీక్షిస్తారు.',
    whatHappensNextItem1: 'ఈ మార్గదర్శకాలను ఉల్లంఘించే కంటెంట్ తీసివేయబడుతుంది',
    whatHappensNextItem2: 'దుర్వినియోగ ప్రవర్తనకు బాధ్యత వహించే ఖాతాలు సస్పెండ్ చేయబడతాయి లేదా పరిమితం చేయబడతాయి',
