    appeals: 'విజ్ఞప్తులు',
    appealsText: 'మితవాద నిర్ణయం తప్పు అని మీరు విశ్వసిస్తే, దానిని కమ్యూనిటీ గవర్నెన్స్ ద్వారా అప్పీల్ చేయవచ్చు. పాలసీ మోడరేటర్ ‌ లు అమలు చేయడాన్ని గవర్నెన్స్ సెట్ చేస్తుంది మరియు వ్యక్తిగత నిర్ణయాలను సమీక్షించవచ్చు లేదా రివర్స్ చేయవచ్చు. అయితే, ఎన్ ‌ ఫోర్స్ ‌ మెంట్ తక్షణమే ఉంటుంది — అప్పీల్ పరిగణించబడుతున్నప్పుడు కంటెంట్ తగ్గుతుంది.',
