    prereq1: 'ఒక వెబ్ బ్రౌజర్, లేదా గూగుల్ ప్లే నుండి ఆండ్రాయిడ్ అప్‌ప్.',
    prereq2: 'గూగుల్, ఆపిల్ లేదా టెలిగ్రాం ఖాతా, ఒక ఇమెయిల్ చిరునామా, ఫోన్ నంబర్ లేదా పాస్‌కీ — లేదా మీరు ఇప్పటికే ఉపయోగిస్తున్న వాలెట్.',
