    step1Title: 'మీ ఖాతాను సృష్టించండి',
    step2Title: 'తమ ప్రొఫైల్‌ను సెట్టింగ్‌ చేయండి',
    step2Desc: 'సెట్టింగ్ ‌ ల → ప్రొఫైల్ ‌ లో డిస్ ‌ ప్లే పేరు, యూజర్ ‌ నేమ్, అవతార్, కవర్ ఇమేజ్ మరియు బయోను జోడించి, మీ ఇతర సోషల్ ‌ లను లింక్ చేయండి, తద్వారా మీ ప్రొఫైల్ మీ మొత్తం పరిధిని చూపుతుంది. → మీరు అక్కడ ఉన్నప్పుడు సెట్టింగ్ ‌ ల స్వరూపంలో థీమ్ ‌ ను ఎంచుకోండి మరియు మీరు చుట్టూ చూపించాలనుకుంటే ఐచ్ఛిక గైడెడ్ వాక్ ‌ థ్రూ తీసుకోండి.',
    step3Title: 'మీ మొదటి పోస్ట్ చేయండి',
    step3Desc: 'సృష్టించు నొక్కండి. పోస్ట్ రాయండి, చిత్రాలు, వీడియో లేదా ఆడియోను జోడించండి, దీర్ఘ-రూపం రచన కోసం ఆర్టికల్ ‌ కు మారండి లేదా లైవ్ ‌ కి వెళ్లండి. పోస్ట్ చేయడం అనేది రోజువారీ భత్యం వరకు ఉచితం — బ్యాడ్జ్ లేకుండా రోజుకు పది టెక్స్ట్ పోస్ట్ ‌ లు మరియు గిగాబైట్ మీడియా. పోస్ట్ ఆన్-చైన్ ‌ ను ముద్రించడం ఐచ్ఛికం మరియు తరువాత చేయవచ్చు.',
    step4Title: 'మీ ప్రేక్షకుల నుండి సంపాదించండి',
    step4Desc: 'ప్రతి పోస్ట్‌ను డీహబ్ టోకెన్లలో టిప్ చేయవచ్చు. అక్కడ నుండి మీరు సబ్స్క్రిప్షన్లను అమ్ముకోవచ్చు, పేయ్-పర్-వ్యూ పోస్ట్‌లను ప్రచురించవచ్చు, డైరెక్ట్ మెసేజ్‌లకు మినిమం టిప్‌ను సెట్ చేయవచ్చు, స్టోర్‌ను తెరవవచ్చు, బౌంటీలను పోస్ట్ చేయవచ్చు, మరియు మీకు తీసుకువచ్చే వ్యక్తుల నుండి ఆదాయం పొందడానికి అఫిలియేట్ లింక్‌ను పంచుకోవచ్చు.',
    step5Title: 'హోల్డ్ టోకెన్స్ కోసం బ్యాడ్జ్‌ను ఉంచుకోండి.',
    step5Desc: 'బ్యాడ్జ్ పొందడం ద్వారా డీహబ్ టోకెన్స్‌ను హోల్డ్ చేయడం లేదా స్టేక్ చేయడం ద్వారా క్రాబ్ నుండి మెగాలోడాన్ వరకు బ్యాడ్జ్ లభిస్తుంది. బ్యాడ్జ్ వల్ల మీ ఫీజులు తగ్గుతాయి, పోస్ట్ చేయడానికి అనుమతి పెరుగుతుంది, సూపర్‌పవర్స్‌ను అన్లాక్ చేస్తుంది, మీ వీక్షణలు, రియాక్షన్లు, ఓట్లకు బరువు పెరుగుతుంది.',
    step6Title: 'మీ వాలెట్‌ను ఉపయోగించండి',
    step6Desc: 'మీ వాలెట్‌లో DeHub టోకెన్లు మరియు వివిధ ఛేన్లపై ఇతర క్రిప్టోక్యూరెన్సీలు ఉన్నాయి. కర్డ్ ద్వారా లేదా క్రిప్టో ద్వారా $0.50 నుండి టోకెన్లను కొనుగోలు చేయండి, ఎవరికి కూడా ఉచితంగా పంపండి, DeHub ఎక్స్చేంజ్‌లో ట్రేడ్ చేయండి, మరియు బ్యాడ్జ్ లడ్డర్‌ను ఎక్కడానికి స్టేక్ చేయండి.',
